// Copies the Portal API specs generated by the backend build (v1 and v2) into `apis/`.
import { access, copyFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const backendSpecs = path.resolve(root, '../devportal-api/openapi')
// The backend's OpenAPI generator names the v2 document `portal-api_v2.json`.
const specs = [
  ['portal-api.json', 'portal-api.json'],
  ['portal-api_v2.json', 'portal-api-v2.json'],
]

for (const [sourceName, targetName] of specs) {
  const source = path.join(backendSpecs, sourceName)
  const target = path.join(root, 'apis', targetName)
  try {
    await access(source)
  } catch {
    console.error(
      `No se encontró la spec de la Portal API en ${source}.\n` +
        'Clonar devportal-api en la misma carpeta que este repo y correr `dotnet build` ahí para generarla.',
    )
    process.exit(1)
  }

  await copyFile(source, target)
  console.log(`Spec copiada: ${source} -> ${target}`)
}
